def _explode_parentheses(paren_string):
    bracket_count, nesting_level = len(paren_string), 0
    nested_result = ''

    for char in paren_string:
        if char in ('(',')'):
            nested_result += char
            nesting_level += 1 if char == '(' else -1
            continue

        if nesting_level == 0:
            yield bracket_count, nesting_level
        else:
            bracket_count += len(nested_result)

        nested_result = ''


