def filter_by_starting_chars(strings: List[str], char: chr) -> List[str]:
    """ Filter an input list of strings only for ones that have given char as first char
    >>> filter_by_starting_chars(['abc', 'bacd', 'cde', 'array'], 'a')
    ['array']
    >>> filter_by_starting_chars(['abc', 'bacd', 'cde', 'array'], 'c')
    ['abc']
    >>> filter_by_starting_chars(['abc', 'bacd', 'cde', 'array'], 'd')
    []
    """
    def check_item(item):
        chars = [c for c in item if c != char]
        if ''.join(chars)[0] == char:
            return item
    return list(filter(check_item, strings))

