    """ Count inversions on a list of numbers.
        An inversion is a pair `a', b`
        in the list with a > b
        >>> count_inversions([4, 3, 2, 1])
        3
        >>> count_inversions([1, 3, 5, 2, 4, 6, 7])
        10
    """
    inversions = 0
    list_len = len(list_)

    for i in range(list_len):
        for j in range(i+1, list_len):
            if descending and list_[i] < list_[j]:
                inversions += 1
            elif not descending and list_[j] < list_[i]:
                inversions += 1

    return inversions

